import{_ as h,C as s,o as d,c,j as t,a,E as o,a8 as p}from"./chunks/framework.27XeWUA0.js";const n="/schedule-dashboard/thumbs/yt/vlfCjWuv4es-640.webp",u="/schedule-dashboard/thumbs/yt/vlfCjWuv4es-1280.webp",r="/schedule-dashboard/thumbs/yt/GGrvSnpPTGo-640.webp",w="/schedule-dashboard/thumbs/yt/GGrvSnpPTGo-1280.webp",T=JSON.parse('{"title":"AI Digest · Fri 13 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-13","routine":"digest"},"relativePath":"digest/2026-11-13.md","filePath":"digest/[date].md"}'),v={name:"digest/2026-11-13.md"},g=n+" 640w, "+u+" 1280w",m=r+" 640w, "+w+" 1280w",f={id:"ai-digest-·-fri-13-nov-2026",tabindex:"-1"};function b(k,e,y,C,_,G){const i=s("Badge"),l=s("DayFilter");return d(),c("div",null,[t("h1",f,[e[0]||(e[0]=a("AI Digest · Fri 13 Nov 2026 ",-1)),o(i,{type:"tip",text:"2"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-fri-13-nov-2026","aria-label":'Permalink to "AI Digest · Fri 13 Nov 2026 <Badge type="tip" text="2" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 13 Nov 2026 · run date Fri 13 Nov 2026 · 2 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(" 1 new talk in the last 24 hours: Anthropic's Lydia Hallie on how Claude Code best practices have changed for the newest models (12 Nov, 8:56 AM IST). It touches well-covered ground (coding agents, sandboxes, human review) but isn't mostly a repeat and is worth watching for its concrete setup advice.")]),t("p",null,[t("strong",null,"Better Stack:"),a(" 1 new video: a review of Theo's open-source tstack skills for testing, reviewing, opening and babysitting PRs (12 Nov, 5:45 PM IST). It's a skim, mainly for the Full Stop demo and the three-model Council review.")])],-1)),o(l),e[5]||(e[5]=p('<div class="grid cards2"><article class="it full" id="v-vlfCjWuv4es" data-title="Rethinking Claude Code Best Practices — Lydia Hallie, Anthropic" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=vlfCjWuv4es" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+g+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=vlfCjWuv4es" target="_blank" rel="noopener">Rethinking Claude Code Best Practices — Lydia Hallie, Anthropic</a></h3><div class="meta">AI Engineer · Lydia Hallie, Anthropic (Claude Code team) · uploaded 12 Nov, 8:56 AM IST · 17:32</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — the most practical Claude Code setup guide in a while, especially the sandbox, hook exit-code and review-tier details.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 83 times before. New here: Anthropic&#39;s own updated Claude Code defaults for the newest models, straight from the Claude Code team.</div><div class="repeat">🔁 Repeat: &#39;sandboxes for agents&#39; — seen 27 times before. New here: a clear explanation of why deny rules alone can&#39;t stop a compromised `npm test` dependency, and how the OS-level sandbox closes that gap.</div><div class="repeat">🔁 Repeat: &#39;human-in-the-loop review&#39; — seen 47 times before. New here: Anthropic&#39;s risk-tiered review (docs need no human, normal changes one reviewer, risky ones two).</div><p class="note"><em>She re-recorded the talk at home after technical problems on stage, so it&#39;s a screen recording with slides.</em></p><div class="sh">Why the old habits now hurt</div><ul><li><strong>From one session to dozens:</strong> Earlier this year sessions with Opus 4.5 stopped early and needed constant correcting; now Anthropic engineers run dozens of hours-long sessions at once. Anthropic went from about 2,500 changes a day in May to over 30,000 a day in September (<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=30s" target="_blank" rel="noopener">0:30</a>–<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=120s" target="_blank" rel="noopener">2:00</a>)</li><li><strong>Trim your CLAUDE.md:</strong> &quot;IMPORTANT!&quot;-style shouting and notes on your stack or where to look now push newer models off track and cause extra tool calls. Keep only what Claude can&#39;t see in the code, like a legacy service that isn&#39;t referenced anywhere. A doctor prompt-audit command checks your CLAUDE.md and skills against the current model (<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=180s" target="_blank" rel="noopener">3:00</a>–<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=240s" target="_blank" rel="noopener">4:00</a>)</li></ul><div class="sh">Keeping long unattended sessions safe</div><ul><li><strong>Auto mode, configured in plain English:</strong> Auto mode (the default since August) runs a classifier on anything beyond reading or editing files; you can tell it in plain English which repos, buckets and domains you trust. In Anthropic&#39;s August study only about 14% of people caught a clearly dangerous command, while auto mode blocked 89%, so roughly one in ten still got through (<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=240s" target="_blank" rel="noopener">4:00</a>–<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=360s" target="_blank" rel="noopener">6:00</a>)</li><li><strong>Deny rules still matter:</strong> A deny rule is checked before the classifier ever sees the call, so use one for anything you can&#39;t undo, such as reading `.env`. The test she gives: if Claude gets it wrong once, can you take it back? (<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=360s" target="_blank" rel="noopener">6:00</a>–<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=420s" target="_blank" rel="noopener">7:00</a>) (repeat)</li><li><strong>Sandbox the side effects:</strong> A deny rule only sees `npm test`, not a compromised dependency inside it reading `.env` or SSH keys. Turning on the sandbox hands the same rules to the operating system, which also covers child processes and blocks unapproved hosts, though MCP servers and hooks still run outside it (<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=420s" target="_blank" rel="noopener">7:00</a>–<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=570s" target="_blank" rel="noopener">9:30</a>)</li><li><strong>Cloud sessions:</strong> Running in Claude&#39;s cloud gives each session a fresh machine and repo copy with no `.env`, SSH keys or GitHub token, network secrets that are never sent to the model, and network access limited to package registries and GitHub by default. Commit deny rules to the repo so they still catch force-pushes or secrets in commits (<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=570s" target="_blank" rel="noopener">9:30</a>–<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=660s" target="_blank" rel="noopener">11:00</a>)</li></ul><div class="sh">Verification instead of watching</div><ul><li><strong>Checkpoints and hooks:</strong> The same &quot;move auth to a new API&quot; prompt can produce three plausible but different results, so define pass/fail checkpoints. For guaranteed checks use hooks: lint on every edit, run the changed area&#39;s tests when a task is marked done, the full suite at session end. Hook scripts must exit with code 2, because exit code 1 lets the task be marked complete anyway (<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=660s" target="_blank" rel="noopener">11:00</a>–<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=810s" target="_blank" rel="noopener">13:30</a>)</li><li><strong>CI and risk-based review:</strong> CI with auto-fix lets Claude repair failing checks, and merge-when-ready can merge once checks pass. At Anthropic every PR is first reviewed by a separate Claude with fresh context; docs and copy changes need no person, ordinary changes one reviewer, risky ones two (<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=840s" target="_blank" rel="noopener">14:00</a>–<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=900s" target="_blank" rel="noopener">15:00</a>)</li><li><strong>One orchestrator session:</strong> Claude Code projects (in beta) let one main session split the work and launch and verify sub-sessions, with context handled automatically. She suggests Fable 5.2 for the orchestrator and Opus 5.5 for the worker threads. Her advice: hand Claude one task much bigger than usual and see where you still get pulled back in (<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=900s" target="_blank" rel="noopener">15:00</a>–<a href="https://www.youtube.com/watch?v=vlfCjWuv4es&amp;t=1050s" target="_blank" rel="noopener">17:30</a>)</li></ul></div></article><article class="it full" id="v-GGrvSnpPTGo" data-title="Theo Just Open-Sourced the Skills He Uses to Ship Code" data-channel="Better Stack" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=GGrvSnpPTGo" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+m+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=GGrvSnpPTGo" target="_blank" rel="noopener">Theo Just Open-Sourced the Skills He Uses to Ship Code</a></h3><div class="meta">Better Stack · Josh (Better Stack) reviewing Theo&#39;s tstack · uploaded 12 Nov, 5:45 PM IST · 8:05</div><div class="verdict v-skim"><b>Verdict:</b> skim from 2:00 — a quick look at the demo and the Council idea is enough; the rest is install steps and general caveats.</div><div class="repeat">🔁 Repeat: &#39;agent skills&#39; — seen 29 times before. New here: a skill pack aimed at everything after the code is written (tests, PRs, CI, merging) rather than writing code.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 39 times before. New here: the Council skill, where Claude, GPT and Gemini review the same change in rounds.</div><div class="sh">What tstack is</div><ul><li><strong>Nine skills for shipping:</strong> tstack is nine instruction files for Claude Code and Codex covering testing, multi-model review, opening PRs, fixing CI failures, taking over unfinished PRs and even merging (<a href="https://www.youtube.com/watch?v=GGrvSnpPTGo&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=GGrvSnpPTGo&amp;t=90s" target="_blank" rel="noopener">1:30</a>)</li><li><strong>Setup:</strong> Clone it and copy the skills into your Claude Code or Codex skills folder. It needs an authenticated GitHub CLI and Python 3 for the PR watcher, and the review skills need access to other providers&#39; models (he uses T3 Code&#39;s delegation tools) (<a href="https://www.youtube.com/watch?v=GGrvSnpPTGo&amp;t=79s" target="_blank" rel="noopener">1:19</a>–<a href="https://www.youtube.com/watch?v=GGrvSnpPTGo&amp;t=118s" target="_blank" rel="noopener">1:58</a>)</li></ul><div class="sh">The demo</div><ul><li><strong>Full Stop on a bug fix:</strong> Typing &quot;full stop&quot; first tries to prove the fix works (reproduce the bug, run tests), then runs Sol Loop to have another model review it, then opens a PR whose description starts with the problem and how it was tested rather than a file list (<a href="https://www.youtube.com/watch?v=GGrvSnpPTGo&amp;t=120s" target="_blank" rel="noopener">2:00</a>–<a href="https://www.youtube.com/watch?v=GGrvSnpPTGo&amp;t=195s" target="_blank" rel="noopener">3:15</a>)</li><li><strong>Babysit PR:</strong> After opening the PR it keeps watching CI and review comments, makes small fixes and re-verifies, but Full Stop never merges; Full Send runs the same chain and merges automatically once required checks and reviews pass (<a href="https://www.youtube.com/watch?v=GGrvSnpPTGo&amp;t=195s" target="_blank" rel="noopener">3:15</a>–<a href="https://www.youtube.com/watch?v=GGrvSnpPTGo&amp;t=265s" target="_blank" rel="noopener">4:25</a>)</li><li><strong>Council, Takeover, Modernize:</strong> Council has three models from different providers review the code over several rounds until they agree; Takeover picks up a PR another agent abandoned; Modernize rebases an old PR and judges whether it&#39;s still needed (<a href="https://www.youtube.com/watch?v=GGrvSnpPTGo&amp;t=270s" target="_blank" rel="noopener">4:30</a>–<a href="https://www.youtube.com/watch?v=GGrvSnpPTGo&amp;t=330s" target="_blank" rel="noopener">5:30</a>)</li></ul><div class="sh">Catches</div><ul><li><strong>Not plug and play:</strong> Council and Sol Loop need extra model access, and the skills call each other (Full Stop calls Full Send, which calls others), so installing one alone breaks. They&#39;re still just instructions to an agent, so you still need permissions, real tests and branch protection (<a href="https://www.youtube.com/watch?v=GGrvSnpPTGo&amp;t=360s" target="_blank" rel="noopener">6:00</a>–<a href="https://www.youtube.com/watch?v=GGrvSnpPTGo&amp;t=420s" target="_blank" rel="noopener">7:00</a>)</li><li><strong>How to start:</strong> Try File PR and Babysit PR first, then Full Stop; consider Full Send only later and only for small, low-risk changes, and customize the skills to your own workflow (<a href="https://www.youtube.com/watch?v=GGrvSnpPTGo&amp;t=420s" target="_blank" rel="noopener">7:00</a>–<a href="https://www.youtube.com/watch?v=GGrvSnpPTGo&amp;t=470s" target="_blank" rel="noopener">7:50</a>)</li></ul></div></article></div>',1))])}const P=h(v,[["render",b]]);export{T as __pageData,P as default};
